mapper.delete:
DELETE FROM user_chat_thinking_history
WHERE user_message_id IN (
    SELECT id
    FROM user_chat_history
    WHERE user_world_id = #{userWorldId}
      AND id > #{maxChatHistoryId}
)

DELETE FROM user_chat_tool_call
WHERE user_message_id IN (
    SELECT id
    FROM user_chat_history
    WHERE user_world_id = #{userWorldId}
      AND id > #{maxChatHistoryId}
)

DELETE FROM user_chat_history
WHERE user_world_id = #{userWorldId}
  AND id > #{maxChatHistoryId}

DELETE FROM user_character_favor_log
WHERE user_world_id = #{userWorldId}
  AND id > #{maxFavorLogId}

DELETE FROM user_event_log
WHERE user_world_id = #{userWorldId}
  AND id > #{maxUserEventLogId}

DELETE FROM world_event_log
WHERE user_world_id = #{userWorldId}
  AND id > #{maxWorldEventLogId}
  AND (
      conversation_id IS NULL
      OR EXISTS (
          SELECT 1
          FROM group_conversation conversation
          WHERE conversation.id = world_event_log.conversation_id
            AND conversation.mode = 'chat'
      )
  )

DELETE FROM group_chat_message message
USING group_conversation conversation
WHERE message.conversation_id = conversation.id
  AND conversation.user_world_id = #{userWorldId}
  AND conversation.mode = 'chat'
  AND message.id > #{maxGroupMessageId}

DELETE FROM group_chat_turn turn_row
USING group_conversation conversation
WHERE turn_row.conversation_id = conversation.id
  AND conversation.user_world_id = #{userWorldId}
  AND conversation.mode = 'chat'
  AND turn_row.id > #{maxGroupTurnId}

DELETE FROM group_context_summary summary
USING group_conversation conversation
WHERE summary.conversation_id = conversation.id
  AND conversation.user_world_id = #{userWorldId}
  AND conversation.mode = 'chat'
  AND summary.id > #{maxGroupContextSummaryId}

DELETE FROM group_chat_topic topic
USING group_conversation conversation
WHERE topic.conversation_id = conversation.id
  AND conversation.user_world_id = #{userWorldId}
  AND conversation.mode = 'chat'
  AND topic.id > #{maxGroupTopicId}

DELETE FROM group_reply_plan plan
USING group_conversation conversation
WHERE plan.conversation_id = conversation.id
  AND conversation.user_world_id = #{userWorldId}
  AND conversation.mode = 'chat'
  AND conversation.id > #{maxGroupConversationId}

DELETE FROM group_chat_member member
USING group_conversation conversation
WHERE member.conversation_id = conversation.id
  AND conversation.user_world_id = #{userWorldId}
  AND conversation.mode = 'chat'
  AND conversation.id > #{maxGroupConversationId}

DELETE FROM group_conversation
WHERE user_world_id = #{userWorldId}
  AND mode = 'chat'
  AND id > #{maxGroupConversationId}

DELETE FROM user_chat_history
WHERE id IN

    #{id}

DELETE FROM user_character_favor_log
WHERE user_world_id = #{userWorldId}
  AND character_id = #{characterId}
  AND binding_type = #{bindingType}
  AND binding_chat = #{bindingChat}
